# Ciência Política — lote L14, terceira leva (parte 1: Q01–Q04, átomos 38–41)
TG="c"
Q = []
TAILS=[" Essa seria a posição predominante na literatura especializada de ciência política.",
 " Trata-se de entendimento consolidado na teoria política contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características do arranjo institucional descrito.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.93*len(C) and gap > 14: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"doutrina de ciência política; CF","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência e legislação eleitoral","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"CF; leis eleitorais","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def X(q,atom,padE,dif,C,E,com,terro,jur=False,lei=False):
    _n[q]=_n.get(q,0)+1
    P(f"Q{q:02d}",[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"{TG}{q:02d}{_n[q]}",jur=jur,lei=lei)
# ---------- Q01 regimes (átomo 38)
X(1,38,"confusao_instituto",4,"Para Guillermo O'Donnell, o autoritarismo burocrático-militar, como o instaurado no Brasil em 1964, surge em sociedades de industrialização avançada, com apoio de militares e tecnocratas, e busca desmobilizar o setor popular.","Para Guillermo O'Donnell, o autoritarismo burocrático-militar, como o instaurado no Brasil em 1964, é típico de sociedades agrárias de baixa modernização, e dispensa o apoio de tecnocratas e a desmobilização do setor popular.","O'Donnell, Reforma e autoritarismo burocrático.","inverte condições de surgimento")
X(1,38,"confusao_instituto",3,"Levitsky e Way definem autoritarismo competitivo como o regime que mantém instituições democráticas formais, como eleições multipartidárias, mas em que o governante abusa do poder do Estado e torna a disputa desigual.","Levitsky e Way definem autoritarismo competitivo como o regime em que a oposição é proibida de disputar eleições, realizadas apenas de forma simbólica, sob um partido único.","Levitsky e Way.","confunde com partido hegemônico")
X(1,38,"confusao_instituto",3,"A expressão democracia iliberal, popularizada por Fareed Zakaria, designa regimes em que há eleições, mas em que os governantes eleitos desrespeitam limites constitucionais e violam direitos e liberdades.","A expressão democracia iliberal, popularizada por Fareed Zakaria, designa regimes sem eleições competitivas, em que o poder é hereditário, mas com ampla garantia de liberdades individuais.","Zakaria.","inverte elementos")
X(1,38,"excecao_omitida",4,"Para Levitsky e Ziblatt, normas informais como a tolerância mútua entre adversários e a reserva institucional no uso das prerrogativas sustentam a democracia, e sua erosão pode produzir retrocesso democrático sem golpe militar clássico.","Para Levitsky e Ziblatt, a democracia só se deteriora por golpes militares, sendo irrelevantes as normas informais diante do desenho das instituições formais.","Levitsky e Ziblatt, Como as democracias morrem.","nega normas informais")
X(1,38,"confusao_instituto",3,"Para Przeworski, a democracia caracteriza-se pela incerteza institucionalizada quanto aos resultados, pois partidos podem perder eleições e há alternância possível no poder.","Para Przeworski, a democracia caracteriza-se pela certeza quanto aos resultados, pois as regras fixam de antemão o vencedor das eleições.","Przeworski.","inverte incerteza")
X(1,38,"confusao_instituto",4,"Na tipologia de Linz e Chehabi, o sultanismo caracteriza-se pelo poder pessoal e arbitrário do governante, com apropriação privada do Estado e predominância da lealdade pessoal.","Na tipologia de Linz e Chehabi, o sultanismo caracteriza-se pela forte institucionalização burocrática, pela ideologia oficial elaborada e pela mobilização de massas conduzida por partido único.","Linz e Chehabi.","confunde com totalitarismo")
X(1,38,"excecao_omitida",3,"Para Hannah Arendt, o totalitarismo distingue-se das tiranias tradicionais pelo uso do terror como essência do regime, por uma ideologia que pretende explicar toda a história e pela atomização das massas.","Para Hannah Arendt, o totalitarismo distingue-se das tiranias tradicionais por dispensar o terror, pois o respeito às leis e às tradições garante a obediência.","Arendt, Origens do totalitarismo.","nega o terror")
X(1,38,"excecao_omitida",3,"Índices como Freedom House, V-Dem e Democracy Index, da Economist Intelligence Unit, medem aspectos da democracia, como direitos políticos, liberdades civis e qualidade eleitoral, e adotam metodologias distintas, o que pode gerar classificações diferentes para um mesmo país.","Índices como Freedom House, V-Dem e Democracy Index adotam metodologia idêntica e classificam cada país sempre do mesmo modo, por usarem exatamente os mesmos indicadores.","Índices de democracia.","afirma metodologia idêntica")
X(1,38,"confusao_instituto",3,"Na literatura sobre transições, a liberalização, que amplia direitos individuais e reduz a repressão, distingue-se da democratização, que implica eleições competitivas e extensão da cidadania.","Na literatura sobre transições, liberalização e democratização são sinônimos, ambos designando a realização de eleições livres e competitivas.","O'Donnell e Schmitter.","identifica liberalização e democratização")
X(1,38,"excecao_omitida",4,"Segundo Barbara Geddes, as ditaduras de partido único tendem a durar mais que as militares e as personalistas, porque o partido distribui benefícios e coopta elites.","Segundo Barbara Geddes, as ditaduras militares tendem a durar mais que as de partido único, porque o partido enfraquece a cooptação de elites.","Geddes.","inverte durabilidade")
X(1,38,"troca_numero",3,"O Ato Institucional n. 5, de dezembro de 1968, ampliou os poderes do Executivo e permitiu o fechamento do Congresso Nacional no regime instaurado em 1964.","O Ato Institucional n. 5, de 1965, extinguiu os partidos existentes e instituiu o bipartidarismo no regime instaurado em 1964.","AI-5.","confunde AI-5 com AI-2")
X(1,38,"confusao_instituto",4,"Para Huntington, a segunda onda reversa, de 1958 a meados da década de 1970, incluiu a instauração de regimes autoritários em países da América Latina, como o Brasil, em 1964.","Para Huntington, a primeira onda reversa teve início em 1974, com a Revolução dos Cravos, em Portugal, quando países da América Latina passaram a restaurar regimes autoritários.","Huntington, A terceira onda.","confunde onda reversa e terceira onda")
# ---------- Q02 sistemas e formas de governo (átomo 39)
X(2,39,"confusao_instituto",3,"No voto de desconfiança construtivo, adotado na Alemanha, o Parlamento só pode destituir o chanceler se, ao mesmo tempo, eleger seu sucessor por maioria, o que confere estabilidade ao governo.","No voto de desconfiança construtivo, adotado na Alemanha, o Parlamento destitui o chanceler por maioria simples, sem necessidade de indicar sucessor, e o presidente pode dissolver a Câmara livremente.","Voto de desconfiança construtivo.","remove exigência de sucessor")
X(2,39,"confusao_instituto",2,"No parlamentarismo, a moção de censura é o instrumento pelo qual o Parlamento retira a confiança do governo, e sua aprovação leva à demissão do gabinete.","No parlamentarismo, a moção de censura é o instrumento pelo qual o chefe de Estado dissolve o Parlamento e convoca novas eleições.","Moção de censura.","confunde com dissolução")
X(2,39,"excecao_omitida",3,"No parlamentarismo, o governo pode, em regra, dissolver o Parlamento e convocar novas eleições, o que funciona como contrapeso à possibilidade de o Parlamento derrubar o gabinete.","No presidencialismo puro, o Presidente pode dissolver o Congresso quando perde a maioria, como contrapeso à possibilidade de o Congresso destituí-lo por moção de censura.","Dissolução do Parlamento.","atribui dissolução ao presidencialismo")
X(2,39,"confusao_instituto",2,"Na monarquia constitucional parlamentar, como a do Reino Unido, o monarca é chefe de Estado com funções predominantemente simbólicas, e o governo é chefiado pelo Primeiro-Ministro, responsável perante o Parlamento.","Na monarquia constitucional parlamentar, como a do Reino Unido, o monarca é chefe de governo e nomeia livremente os ministros, sem responsabilidade perante o Parlamento.","Monarquia parlamentar.","atribui chefia de governo ao monarca")
X(2,39,"confusao_instituto",3,"Para Duverger, o semipresidencialismo combina presidente eleito por sufrágio universal, com poderes consideráveis, e primeiro-ministro e ministros responsáveis perante o Parlamento, como na França da V República.","Para Duverger, o semipresidencialismo combina presidente eleito pelo Parlamento, sem poderes relevantes, e primeiro-ministro eleito diretamente pelo povo, como na França da V República.","Duverger.","inverte eleição do presidente")
X(2,39,"troca_numero",4,"Em 1961, a Emenda Constitucional n. 4 instituiu o parlamentarismo no Brasil após a renúncia de Jânio Quadros, e o plebiscito de janeiro de 1963 restabeleceu o presidencialismo.","Em 1961, a Emenda Constitucional n. 4 instituiu o parlamentarismo no Brasil após a renúncia de Jânio Quadros, e o plebiscito de janeiro de 1963 manteve o parlamentarismo, que só foi extinto pelo golpe de 1964.","Parlamentarismo de 1961.","inverte resultado do plebiscito")
X(2,39,"excecao_omitida",4,"No Segundo Reinado, o chamado parlamentarismo às avessas decorria de ser o Imperador quem escolhia o presidente do Conselho, que depois obtinha a maioria por meio da dissolução da Câmara e de eleições controladas.","No Segundo Reinado, o parlamentarismo seguia o modelo inglês, e o presidente do Conselho era escolhido pela maioria eleita da Câmara, sem possibilidade de dissolução pelo Imperador.","Parlamentarismo às avessas.","nega o papel do Imperador")
X(2,39,"confusao_instituto",3,"Na confederação, os Estados membros conservam a soberania e podem retirar-se da união, ao passo que na federação os Estados têm autonomia política, mas não soberania, e não dispõem do direito de secessão.","Na federação, os Estados membros são soberanos e dispõem do direito de secessão, ao passo que na confederação a soberania pertence ao ente central.","Federação e confederação.","inverte soberania")
X(2,39,"excecao_omitida",3,"No Brasil, a união dos entes federados é indissolúvel e a forma federativa de Estado não pode ser objeto de deliberação de proposta de emenda tendente a aboli-la.","No Brasil, a forma federativa de Estado pode ser abolida por emenda constitucional, desde que aprovada em dois turnos por três quintos dos membros de cada Casa.","CF, arts. 1º e 60, § 4º, I.","nega cláusula pétrea",lei=True)
X(2,39,"excecao_omitida",3,"Na competência concorrente, a União estabelece normas gerais e os Estados e o Distrito Federal exercem competência suplementar, e a edição de normas gerais pela União não suprime a competência suplementar dos Estados.","Na competência concorrente, a edição de normas gerais pela União exclui a competência suplementar dos Estados e do Distrito Federal sobre a matéria.","CF, art. 24, §§ 1º a 4º.","nega competência suplementar",lei=True)
X(2,39,"confusao_instituto",2,"Na Alemanha e na Itália, o presidente da República é chefe de Estado, com funções predominantemente representativas, e o chefe de governo é, respectivamente, o chanceler e o presidente do Conselho de Ministros.","Na Alemanha, o chanceler é chefe de Estado e o presidente federal é chefe de governo, ao passo que na Itália os dois cargos se confundem na pessoa do presidente da República.","Chefia de Estado e de governo.","inverte as chefias")
X(2,39,"excecao_omitida",3,"O Estado unitário pode ser centralizado ou descentralizado administrativamente, e a descentralização, nesse caso, não implica autonomia política dos entes, ao contrário do que ocorre na federação.","A descentralização do Estado unitário concede aos entes autonomia política plena, inclusive Constituição própria, como no federalismo.","Estado unitário.","confunde unitário e federal")
# ---------- Q03 representação (átomo 40)
X(3,40,"confusao_instituto",3,"Na distinção de O'Donnell, a accountability vertical é exercida pelos cidadãos sobre os governantes, sobretudo por meio de eleições, e a horizontal, por agências estatais que fiscalizam outras, como tribunais de contas e Ministério Público.","Na distinção de O'Donnell, a accountability horizontal é exercida pelos cidadãos sobre os governantes, por meio de eleições, e a vertical, por agências estatais que fiscalizam outras, como tribunais de contas.","O'Donnell, accountability.","inverte vertical e horizontal")
X(3,40,"confusao_instituto",4,"Para Bernard Manin, o governo representativo passou do parlamentarismo clássico à democracia de partido e, depois, à democracia de público, na qual ganham relevo a personalização e a comunicação de massa nas escolhas eleitorais.","Para Bernard Manin, o governo representativo passou da democracia de público à democracia de partido e, depois, ao parlamentarismo de notáveis, com redução da importância da mídia nas escolhas eleitorais.","Manin.","inverte a sequência")
X(3,40,"confusao_instituto",3,"Para Sieyès, a nação é soberana e os representantes exprimem a vontade nacional, e não a das circunscrições que os elegeram, ideia que fundamenta o mandato representativo livre.","Para Sieyès, o mandato é imperativo, e os representantes devem cumprir as instruções dos eleitores sob pena de revogação do mandato.","Sieyès.","atribui mandato imperativo")
X(3,40,"confusao_instituto",3,"Para Rousseau, a soberania não pode ser representada, pois a vontade geral é inalienável, de modo que os deputados do povo seriam apenas comissários, sem poder de decidir definitivamente.","Para Rousseau, a representação é a forma ideal de exercício da soberania, pois permite que os representantes decidam em nome do povo de modo definitivo.","Rousseau.","inverte tese sobre representação")
X(3,40,"troca_numero",3,"A Lei 9.504/1997 exige que cada partido ou coligação preencha o mínimo de 30% e o máximo de 70% das candidaturas de cada sexo nas eleições proporcionais.","A Lei 9.504/1997 exige que cada partido ou coligação preencha o mínimo de 20% e o máximo de 80% das candidaturas de cada sexo nas eleições proporcionais.","Lei 9.504/1997, art. 10, § 3º.","altera percentuais",lei=True)
X(3,40,"excecao_omitida",4,"A EC 111/2021 estabeleceu que os votos dados a candidatas mulheres ou a candidatos negros para a Câmara dos Deputados serão contados em dobro, para fins de distribuição dos recursos do fundo partidário e do FEFC, nas eleições de 2022 a 2030.","A EC 111/2021 estabeleceu que os votos dados a candidatas mulheres ou a candidatos negros para a Câmara dos Deputados serão contados em dobro para fins de distribuição das cadeiras entre os partidos, nas eleições de 2022 a 2030.","EC 111/2021.","altera efeito da contagem em dobro",lei=True)
X(3,40,"confusao_instituto",2,"Na lista fechada e bloqueada, o eleitor vota na legenda e a ordem de ocupação das cadeiras é definida previamente pelo partido, ao passo que na lista aberta a ordem decorre dos votos nominais recebidos pelos candidatos.","Na lista aberta, a ordem de ocupação das cadeiras é definida previamente pelo partido, ao passo que na lista fechada e bloqueada decorre dos votos nominais recebidos.","Lista aberta e fechada.","inverte as listas")
X(3,40,"excecao_omitida",4,"A baixa proporção de mulheres na Câmara dos Deputados, em comparação com sua proporção na população, é apontada como déficit de representação descritiva, embora, segundo Pitkin, a representação substantiva possa ser exercida por parlamentares de qualquer sexo.","A baixa proporção de mulheres na Câmara dos Deputados demonstra, segundo Pitkin, que a representação substantiva só é possível por parlamentares pertencentes ao mesmo grupo social dos representados.","Pitkin.","afirma exclusividade do grupo")
X(3,40,"excecao_omitida",3,"A Constituição de 1988 não prevê o recall, instituto que permite aos eleitores revogar o mandato de um representante antes do término do período.","A Constituição de 1988 prevê o recall do Presidente da República, que pode ter o mandato revogado por plebiscito antes do término do período.","Recall.","inventa recall presidencial",lei=True)
X(3,40,"confusao_instituto",4,"Para Schmitter, no corporativismo a representação de interesses se dá por um número limitado de associações monopolistas, reconhecidas ou criadas pelo Estado, ao passo que no pluralismo as associações são múltiplas, voluntárias e competitivas.","Para Schmitter, no pluralismo a representação de interesses se dá por associações monopolistas criadas pelo Estado, ao passo que no corporativismo as associações são múltiplas, voluntárias e competitivas.","Schmitter.","inverte corporativismo e pluralismo")
X(3,40,"excecao_omitida",4,"Pela Lei 9.709/1998, nas questões de relevância nacional o plebiscito e o referendo são convocados mediante decreto legislativo, por proposta de, no mínimo, um terço dos membros de qualquer das Casas do Congresso Nacional.","Pela Lei 9.709/1998, nas questões de relevância nacional o plebiscito e o referendo são convocados por decreto do Presidente da República, por proposta da maioria absoluta dos membros do Congresso Nacional.","Lei 9.709/1998, art. 3º.","altera forma e quórum de convocação",lei=True)
X(3,40,"excecao_omitida",3,"O voto é obrigatório para os maiores de dezoito anos e facultativo para os analfabetos, os maiores de setenta anos e os maiores de dezesseis e menores de dezoito anos.","O voto é obrigatório para os maiores de dezesseis anos e facultativo apenas para os analfabetos e os maiores de sessenta e cinco anos.","CF, art. 14, § 1º.","altera faixas etárias",lei=True)
# ---------- Q04 poderes (átomo 41)
X(4,41,"troca_numero",3,"A medida provisória, editada em caso de relevância e urgência, tem força de lei e perde a eficácia, desde a edição, se não for convertida em lei no prazo de sessenta dias, prorrogável uma vez por igual período.","A medida provisória, editada em caso de relevância e urgência, tem força de lei e perde a eficácia, desde a edição, se não for convertida em lei no prazo de trinta dias, prorrogável uma vez por igual período.","CF, art. 62, § 3º.","altera prazo",lei=True)
X(4,41,"excecao_omitida",4,"Se a medida provisória não for apreciada em até quarenta e cinco dias contados de sua publicação, entra em regime de urgência e ficam sobrestadas, até que se ultime a votação, todas as demais deliberações legislativas da Casa em que estiver tramitando.","Se a medida provisória não for apreciada em até quarenta e cinco dias contados de sua publicação, entra em regime de urgência apenas no Senado Federal, sem sobrestamento das demais deliberações legislativas.","CF, art. 62, § 6º.","afasta sobrestamento",lei=True)
X(4,41,"excecao_omitida",4,"O Presidente da República pode solicitar urgência para projetos de sua iniciativa, e, se a Câmara e o Senado não se manifestarem em até quarenta e cinco dias cada um, sobrestam-se as demais deliberações da Casa, exceto as de prazo constitucional determinado.","O Presidente da República pode solicitar urgência para projetos de sua iniciativa, e, se a Câmara e o Senado não se manifestarem em até quarenta e cinco dias cada um, sobrestam-se todas as demais deliberações da Casa, sem exceção.","CF, art. 64, §§ 1º e 2º.","omite exceção",lei=True)
X(4,41,"troca_numero",3,"O Presidente da República pode vetar projeto de lei, total ou parcialmente, no prazo de quinze dias úteis contados do recebimento, e o veto pode ser rejeitado pelo voto da maioria absoluta dos Deputados e Senadores, em sessão conjunta.","O Presidente da República pode vetar projeto de lei, total ou parcialmente, no prazo de quinze dias úteis contados do recebimento, e o veto só pode ser rejeitado pelo voto de dois terços dos Deputados e Senadores, em sessão conjunta.","CF, art. 66.","altera quórum de derrubada",lei=True)
X(4,41,"confusao_instituto",4,"Para George Tsebelis, jogadores com poder de veto são atores cujo consentimento é necessário para mudar o status quo, e quanto maior o número desses atores e a distância ideológica entre eles, maior a estabilidade das políticas.","Para George Tsebelis, jogadores com poder de veto são atores cujo consentimento é necessário para mudar o status quo, e quanto maior o número desses atores e a distância ideológica entre eles, menor a estabilidade das políticas.","Tsebelis.","inverte efeito sobre estabilidade")
X(4,41,"confusao_instituto",3,"Para Scott Mainwaring, a combinação de presidencialismo, multipartidarismo e representação proporcional é desfavorável à estabilidade democrática, o que o levou a falar em uma combinação difícil.","Para Scott Mainwaring, a combinação de presidencialismo, multipartidarismo e representação proporcional é a mais favorável à estabilidade democrática, pois assegura maioria própria ao Presidente.","Mainwaring.","inverte avaliação")
X(4,41,"troca_numero",3,"As emendas individuais ao orçamento tornaram-se de execução obrigatória pela EC 86/2015, e as emendas de bancada, pela EC 100/2019.","As emendas individuais ao orçamento tornaram-se de execução obrigatória pela EC 100/2019, e as emendas de bancada, pela EC 86/2015.","EC 86/2015 e EC 100/2019.","troca emendas",lei=True)
X(4,41,"excecao_omitida",3,"Em dezembro de 2022, o STF julgou inconstitucional o chamado orçamento secreto, caracterizado pelas emendas do relator (RP-9), por ofensa aos princípios da transparência e da impessoalidade.","Em dezembro de 2022, o STF julgou constitucional o chamado orçamento secreto, caracterizado pelas emendas do relator (RP-9), por tratar-se de matéria interna corporis do Poder Legislativo.","ADPF 854 e conexas.","inverte resultado do julgamento",jur=True)
X(4,41,"confusao_instituto",4,"A Constituição de 1824 previa quatro poderes políticos, Legislativo, Moderador, Executivo e Judicial, e o Poder Moderador era privativo do Imperador, que podia, entre outras funções, dissolver a Câmara dos Deputados.","A Constituição de 1824 previa três poderes e o Imperador exercia o Poder Moderador apenas por meio de ministros, sendo-lhe vedado dissolver a Câmara dos Deputados.","CF/1824, arts. 10 e 98 a 101.","reduz poderes e retira atribuições do Imperador")
X(4,41,"confusao_instituto",3,"A dificuldade contramajoritária consiste na tensão entre o controle de constitucionalidade exercido por juízes não eleitos e a vontade de representantes eleitos pela maioria.","A dificuldade contramajoritária consiste na vinculação do Supremo Tribunal Federal às decisões da maioria parlamentar, que o impede de invalidar leis.","Bickel.","inverte sentido da expressão")
X(4,41,"confusao_instituto",3,"Para Luís Roberto Barroso, a judicialização decorre do modelo constitucional adotado e é um fato, ao passo que o ativismo judicial é uma atitude, uma escolha de modo proativo e expansivo de interpretar a Constituição.","Para Luís Roberto Barroso, a judicialização é uma atitude do juiz, uma escolha de interpretação expansiva, ao passo que o ativismo judicial decorre do modelo constitucional e é um fato.","Barroso.","inverte judicialização e ativismo")
X(4,41,"excecao_omitida",3,"O Congresso Nacional exerce o controle externo com o auxílio do Tribunal de Contas da União, que apura as contas do Presidente da República mediante parecer prévio, cabendo o julgamento dessas contas ao próprio Congresso.","O Tribunal de Contas da União julga as contas do Presidente da República, e o Congresso Nacional limita-se a tomar conhecimento da decisão.","CF, arts. 49, IX, e 71, I.","atribui julgamento ao TCU",lei=True)
X(4,41,"confusao_instituto",3,"No Federalista n. 51, Madison sustenta que a ambição deve ser contraposta à ambição, para que cada poder tenha meios e motivos pessoais de resistir às invasões dos demais.","No Federalista n. 51, Madison sustenta que os poderes devem ser fundidos em um único órgão colegiado, para evitar a rivalidade entre os governantes.","Madison.","inverte tese dos checks and balances")
